int gcd(int a, int b) {
    while (b != 0) {
        int t = a % b;
        a = b;
        b = t;
    }
    return a;
}

tests:
int main(void) {
    if (gcd(12, 18) != 6) return 1;
    if (gcd(0, 5) != 5) return 2;
    if (gcd(7, 13) != 1) return 3;
    if (gcd(270, 192) != 6) return 4;
    printf("OK\n");
    return 0;
}

