int max_subarray_sum(const int *xs, int n) {
    int best = xs[0], current = xs[0];
    for (int i = 1; i < n; i++) {
        current = xs[i] > current + xs[i] ? xs[i] : current + xs[i];
        if (current > best) best = current;
    }
    return best;
}

