#include <ctype.h>
#include <string.h>

int is_palindrome(const char *s) {
    int i = 0, j = (int)strlen(s) - 1;
    while (i < j) {
        while (i < j && !isalnum((unsigned char)s[i])) i++;
        while (i < j && !isalnum((unsigned char)s[j])) j--;
        if (tolower((unsigned char)s[i]) != tolower((unsigned char)s[j])) return 0;
        i++; j--;
    }
    return 1;
}

tests:
int main(void) {
    if (is_palindrome("A man, a plan, a canal: Panama") != 1) return 1;
    if (is_palindrome("hello") != 0) return 2;
    if (is_palindrome("") != 1) return 3;
    printf("OK\n");
    return 0;
}
